```python
def version_key(s):
    components = s.split('.')
    nums = []
    for comp in components:
        num = int(comp) if comp else 0
        nums.append(num)
    # Drop trailing zeros
    while nums and nums[-1] == 0:
        nums.pop()
    return tuple(nums)
```

